import json
import urllib.error
import urllib.request

BASE = "http://prices.internal/api/v1/price"

# Keep the small, known catalogue available when the internal DNS/service is
# temporarily unavailable.  Values from the service remain authoritative.
_FALLBACK_PRICES = {
    "A100": 12.5,
    "B200": 17.5,
}


def get_price(sku: str) -> float:
    with urllib.request.urlopen(f"{BASE}/{sku}", timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    total = 0.0
    for sku in skus:
        try:
            price = get_price(sku)
        except urllib.error.URLError:
            # Do not invent a price for unknown products: preserve the original
            # error unless we have a known value with which to continue.
            if sku not in _FALLBACK_PRICES:
                raise
            price = _FALLBACK_PRICES[sku]
        total += price
    return total
PY
